# Let me check if there's any pattern I'm missing by looking at the differences again
# but being more systematic

inputs = ['fhfzc', 'hagi', 'kycjwv', 'daaafv', 'bziug']
outputs = ['fhfcwvc', 'hagi', 'kycuwv', 'daaafv', 'aiabccwviug']

# Let me examine if there are any other character substitutions I missed
print("Analyzing potential transformations:")

# Build up all the character substitutions I can see:
transformations = {}

for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"\n{i+1}. '{inp}' → '{outp}':")
    min_len = min(len(inp), len(outp))
    for j in range(min_len):
        if inp[j] != outp[j]:
            print(f"   Position {j}: '{inp[j]}' → '{outp[j]}'")
            if inp[j] not in transformations:
                transformations[inp[j]] = outp[j]

    # Check if there are length differences that might indicate a pattern
    if len(inp) != len(outp):
        print(f"   Length difference: {len(inp)} → {len(outp)}")

print("\nAll transformations seen:")
for char_in, char_out in transformations.items():
    print(f"  '{char_in}' → '{char_out}'")

